async function factoryPhasePending(mode:'RR'|'FINAL_RC'){
 await inventoryFixture(async f=>{
  const h=installControl(f),source=await produceControl(f,h),pool=f.access.pool,connect=pool.connect.bind(pool),trace:Array<{no:number;phase:string;factory:boolean;sql:string}>=[],releases:Array<{no:number;error:boolean}>=[];
  const authBefore=h.historyAuth;let serial=0,targetNo=0,started=0,lateOutcome=0,lateResolve:null|(()=>void)=null;
  pool.connect=async()=>{const no=++serial,client=await connect();let phase='RC',factory=false;return{async query(sql:string,args:any[]=[]){if(sql.startsWith('BEGIN'))phase=sql.includes('REPEATABLE')?'RR':'RC';if(sql.includes("to_regclass('anvil.control_handoff_source_requests')"))factory=true;trace.push({no,phase,factory,sql});
   const target=factory&&(mode==='RR'?phase==='RR'&&sql.startsWith('WITH inventory_row AS (')&&sql.includes('FROM anvil.control_handoff_source_requests t'):phase==='RC'&&h.historyCalls===3&&sql.includes('FROM anvil.auth_sessions'));
   const pending=client.query(sql,args);if(!target)return pending;
   started++;assert.equal(started,1);targetNo=no;
   const observed=pending.then((result:any)=>({result,error:null}),(error:any)=>({result:null,error}));
   return await new Promise<any>((resolve,reject)=>{lateResolve=()=>{void observed.then((out:{result:any;error:any})=>{lateOutcome++;if(out.error)reject(out.error);else resolve(out.result);});};});
  },release(error?:Error){releases.push({no,error:error!==undefined});return client.release(error);}};};
  const input={projectId:pid,limits:{...limits,deadlineMs:150}};
  await assert.rejects(composeProjectInventory(f.access,token,input,new AbortController().signal,controlContext(f,source)),rejected(503));
  assert.equal(started,1);assert.equal(targetNo,mode==='RR'?3:4,'Root client1과 factory 최초RC2/RR3/최종RC4를 구분');
  assert.equal(releases.filter(x=>x.no===1).length,1,'Root 최초인증 client는 먼저 종료');assert.equal(releases.filter(x=>x.no===targetNo).length,1,'자기 pending client는 정확1회 회수');assert.equal(releases.find(x=>x.no===targetNo)!.error,true);
  assert(trace.some(x=>x.no===2&&x.factory&&x.sql.includes('FROM anvil.auth_sessions')),'실제 factory 최초 인증 선행');assert(trace.some(x=>x.no===2&&x.factory&&x.sql.startsWith('WITH inventory_row AS (')),'최초 RC 본인자료 정상 검산 선행');
  const point=trace.findIndex(x=>x.no===targetNo&&(mode==='RR'?x.sql.startsWith('WITH inventory_row AS ('):x.sql.includes('FROM anvil.auth_sessions')));assert(point>=0);assert(trace.slice(0,point).some(x=>x.no===targetNo&&x.sql==='SELECT id,checksum FROM anvil.schema_migrations WHERE id=$1'));
  if(mode==='RR'){assert.equal(h.historyCalls,2);assert.equal(h.historyAuth-authBefore,1);}else{assert.equal(h.historyCalls,3);assert.equal(h.historyAuth-authBefore,2);assert(trace.some(x=>x.no===3&&x.phase==='RR'&&x.sql==='ROLLBACK'),'RR 검산과 회수 뒤 최종RC에서 대기');}
  assert.equal(f.state.lastOldTable,'');assert.equal(f.state.featureQueries.length,0);assert.equal(f.io.calls.length,0);assert.equal(f.state.active,0);assert.equal(lateOutcome,0);assert(lateResolve);
  const queryCount=trace.length,releaseCount=releases.length;(lateResolve as ()=>void)();await new Promise(r=>setImmediate(r));assert.equal(lateOutcome,1);assert.equal(trace.length,queryCount,'늦은 결과 뒤 새query0');assert.equal(releases.length,releaseCount,'늦은 결과 뒤 재release0');assert.equal(new Set(releases.map(x=>x.no)).size,releases.length);
 });
}
test('control handoff history profile factory RR own SELECT pending observes late outcome once and no old24',()=>factoryPhasePending('RR'));
test('control handoff history profile factory finalRC actual authentication pending observes late outcome once and no old24',()=>factoryPhasePending('FINAL_RC'));
